175	bool HttpServer::receiveRequest()
176	{
177	  if (socketRecvBuffer_->bufferEmpty()) {
178	    if (socketRecvBuffer_->recv() == 0 && !socket_->wantRead() &&
179	        !socket_->wantWrite()) {
180	      throw DL_ABORT_EX(EX_EOF_FROM_PEER);
181	    }
182	  }
183	  if (headerProcessor_->parse(socketRecvBuffer_->getBuffer(),
184	                              socketRecvBuffer_->getBufferLength())) {
185	    lastRequestHeader_ = headerProcessor_->getResult();
186	    A2_LOG_INFO(fmt("HTTP Server received request\n%s",
187	                    headerProcessor_->getHeaderString().c_str()));
188	    socketRecvBuffer_->drain(headerProcessor_->getLastBytesProcessed());
189	    bodyConsumed_ = 0;
190	    if (setupResponseRecv() < 0) {
191	      A2_LOG_INFO("Request path is invalid. Ignore the request body.");
192	    }
193	    const std::string& contentLengthHdr =
194	        lastRequestHeader_->find(HttpHeader::CONTENT_LENGTH);
195	    if (!contentLengthHdr.empty()) {
196	      if (!util::parseLLIntNoThrow(lastContentLength_, contentLengthHdr) ||
197	          lastContentLength_ < 0) {
198	        throw DL_ABORT_EX(
199	            fmt("Invalid Content-Length=%s", contentLengthHdr.c_str()));
200	      }
201	    }
202	    else {
203	      lastContentLength_ = 0;
204	    }
205	    headerProcessor_->clear();
206	
207	    std::vector<Scip> acceptEncodings;
208	    const std::string& acceptEnc =
209	        lastRequestHeader_->find(HttpHeader::ACCEPT_ENCODING);
210	    util::splitIter(acceptEnc.begin(), acceptEnc.end(),
211	                    std::back_inserter(acceptEncodings), ',', true);
212	    acceptsGZip_ = false;
213	    for (std::vector<Scip>::const_iterator i = acceptEncodings.begin(),
214	                                           eoi = acceptEncodings.end();
215	         i != eoi; ++i) {
216	      if (util::strieq((*i).first, (*i).second, "gzip")) {
217	        acceptsGZip_ = true;
218	        break;
219	      }
220	    }
221	    return true;
222	  }
223	  else {
224	    socketRecvBuffer_->drain(headerProcessor_->getLastBytesProcessed());
225	    return false;
226	  }
227	}
228	
229	bool HttpServer::receiveBody()
230	{
231	  if (lastContentLength_ == bodyConsumed_) {
232	    return true;
233	  }
234	  if (socketRecvBuffer_->bufferEmpty()) {
235	    if (socketRecvBuffer_->recv() == 0 && !socket_->wantRead() &&
236	        !socket_->wantWrite()) {
237	      throw DL_ABORT_EX(EX_EOF_FROM_PEER);
238	    }
239	  }
240	  size_t length =
241	      std::min(socketRecvBuffer_->getBufferLength(),
242	               static_cast<size_t>(lastContentLength_ - bodyConsumed_));
243	  if (lastBody_) {
244	    lastBody_->writeData(socketRecvBuffer_->getBuffer(), length, 0);
245	  }
246	  socketRecvBuffer_->drain(length);
247	  bodyConsumed_ += length;
248	  return lastContentLength_ == bodyConsumed_;
249	}
