321	bool HttpServer::authenticate()
322	{
323	  if (!username_) {
324	    return true;
325	  }
326	
327	  const std::string& authHeader =
328	      lastRequestHeader_->find(HttpHeader::AUTHORIZATION);
329	  if (authHeader.empty()) {
330	    return false;
331	  }
332	  auto p = util::divide(std::begin(authHeader), std::end(authHeader), ' ');
333	  if (!util::streq(p.first.first, p.first.second, "Basic")) {
334	    return false;
335	  }
336	
337	  std::string userpass = base64::decode(p.second.first, p.second.second);
338	  auto up = util::divide(std::begin(userpass), std::end(userpass), ':', false);
339	  std::string username(up.first.first, up.first.second);
340	  std::string password(up.second.first, up.second.second);
341	  return *username_ == hmac_->getResult(username) &&
342	         (!password_ || *password_ == hmac_->getResult(password));
343	}
344	
345	void HttpServer::setUsernamePassword(const std::string& username,
346	                                     const std::string& password)
347	{
348	  using namespace util::security;
349	
350	  if (!hmac_) {
351	    hmac_ = HMAC::createRandom();
352	  }
353	
354	  if (!username.empty()) {
355	    username_ = make_unique<HMACResult>(hmac_->getResult(username));
356	  }
357	  else {
358	    username_.reset();
359	  }
360	
361	  if (!password.empty()) {
362	    password_ = make_unique<HMACResult>(hmac_->getResult(password));
363	  }
364	  else {
365	    password_.reset();
366	  }
367	}
368	
369	int HttpServer::setupResponseRecv()
370	{
371	  std::string path = createPath();
372	  if (getMethod() == "GET") {
373	    if (path == "/jsonrpc") {
374	      reqType_ = RPC_TYPE_JSONP;
375	      lastBody_.reset();
376	      return 0;
377	    }
378	  }
379	  else if (getMethod() == "POST") {
380	    if (path == "/jsonrpc") {
381	      if (reqType_ != RPC_TYPE_JSON) {
382	        reqType_ = RPC_TYPE_JSON;
383	        lastBody_ = make_unique<json::JsonDiskWriter>();
384	      }
385	      return 0;
386	    }
387	#ifdef ENABLE_XML_RPC
388	    if (path == "/rpc") {
389	      if (reqType_ != RPC_TYPE_XML) {
390	        reqType_ = RPC_TYPE_XML;
391	        lastBody_ = make_unique<rpc::XmlRpcDiskWriter>();
392	      }
393	      return 0;
394	    }
395	#endif // ENABLE_XML_RPC
396	  }
397	  reqType_ = RPC_TYPE_NONE;
398	  lastBody_.reset();
399	  return -1;
400	}
401	
402	std::string HttpServer::createPath() const
403	{
404	  std::string reqPath = getRequestPath();
405	  size_t i;
406	  size_t len = reqPath.size();
407	  for (i = 0; i < len; ++i) {
408	    if (reqPath[i] == '#' || reqPath[i] == '?') {
409	      break;
410	    }
411	  }
412	  reqPath = reqPath.substr(0, i);
413	  if (reqPath.empty()) {
414	    reqPath = "/";
415	  }
416	  return reqPath;
417	}
418	
419	std::string HttpServer::createQuery() const
420	{
421	  std::string reqPath = getRequestPath();
422	  size_t i;
423	  size_t len = reqPath.size();
424	  for (i = 0; i < len; ++i) {
425	    if (reqPath[i] == '#' || reqPath[i] == '?') {
426	      break;
427	    }
428	  }
429	  if (i == len || reqPath[i] == '#') {
430	    return "";
431	  }
432	  else {
433	    size_t start = i;
434	    for (; i < len; ++i) {
435	      if (reqPath[i] == '#') {
436	        break;
437	      }
438	    }
439	    return reqPath.substr(start, i - start);
440	  }
441	}
442	
443	DiskWriter* HttpServer::getBody() const { return lastBody_.get(); }
444	
445	bool HttpServer::supportsPersistentConnection() const
446	{
447	  return keepAlive_ && lastRequestHeader_ && lastRequestHeader_->isKeepAlive();
448	}
449	
450	bool HttpServer::wantRead() const { return socket_->wantRead(); }
451	
452	bool HttpServer::wantWrite() const { return socket_->wantWrite(); }
453	
454	} // namespace aria2
