53	HttpListenCommand::HttpListenCommand(cuid_t cuid, DownloadEngine* e, int family,
54	                                     bool secure)
55	    : Command(cuid), e_(e), family_(family), secure_(secure)
56	{
57	}
58	
59	HttpListenCommand::~HttpListenCommand()
60	{
61	  if (serverSocket_) {
62	    e_->deleteSocketForReadCheck(serverSocket_, this);
63	  }
64	}
65	
66	bool HttpListenCommand::execute()
67	{
68	  if (e_->getRequestGroupMan()->downloadFinished() || e_->isHaltRequested()) {
69	    return true;
70	  }
71	  try {
72	    if (serverSocket_->isReadable(0)) {
73	      std::shared_ptr<SocketCore> socket(serverSocket_->acceptConnection());
74	      socket->setTcpNodelay(true);
75	      auto endpoint = socket->getPeerInfo();
76	
77	      A2_LOG_INFO(fmt("RPC: Accepted the connection from %s:%u.",
78	                      endpoint.addr.c_str(), endpoint.port));
79	
80	      e_->setNoWait(true);
81	      e_->addCommand(
82	          make_unique<HttpServerCommand>(e_->newCUID(), e_, socket, secure_));
83	    }
84	  }
85	  catch (RecoverableException& e) {
86	    A2_LOG_DEBUG_EX(fmt(MSG_ACCEPT_FAILURE, getCuid()), e);
87	  }
88	  e_->addCommand(std::unique_ptr<Command>(this));
89	  return false;
90	}
91	
92	bool HttpListenCommand::bindPort(uint16_t port)
93	{
94	  if (serverSocket_) {
95	    e_->deleteSocketForReadCheck(serverSocket_, this);
96	  }
97	  serverSocket_ = std::make_shared<SocketCore>();
98	  const int ipv = (family_ == AF_INET) ? 4 : 6;
99	  try {
100	    int flags = 0;
101	    if (e_->getOption()->getAsBool(PREF_RPC_LISTEN_ALL)) {
102	      flags = AI_PASSIVE;
103	    }
104	    serverSocket_->bind(nullptr, port, family_, flags);
105	    serverSocket_->beginListen();
106	    A2_LOG_INFO(fmt(MSG_LISTENING_PORT, getCuid(), port));
107	    e_->addSocketForReadCheck(serverSocket_, this);
108	    A2_LOG_NOTICE(fmt(_("IPv%d RPC: listening on TCP port %u"), ipv, port));
109	    return true;
110	  }
111	  catch (RecoverableException& e) {
112	    A2_LOG_ERROR_EX(fmt("IPv%d RPC: failed to bind TCP port %u", ipv, port), e);
113	    serverSocket_->closeConnection();
114	  }
115	  return false;
116	}
