266	void HttpServer::feedResponse(int status, const std::string& headers,
267	                              std::string text, const std::string& contentType)
268	{
269	  std::string httpDate = Time().toHTTPDate();
270	  std::string header =
271	      fmt("HTTP/1.1 %s\r\n"
272	          "Date: %s\r\n"
273	          "Content-Length: %lu\r\n"
274	          "Expires: %s\r\n"
275	          "Cache-Control: no-cache\r\n",
276	          getStatusString(status), httpDate.c_str(),
277	          static_cast<unsigned long>(text.size()), httpDate.c_str());
278	  if (!contentType.empty()) {
279	    header += "Content-Type: ";
280	    header += contentType;
281	    header += "\r\n";
282	  }
283	  if (!allowOrigin_.empty()) {
284	    header += "Access-Control-Allow-Origin: ";
285	    header += allowOrigin_;
286	    header += "\r\n";
287	  }
288	  if (supportsGZip()) {
289	    header += "Content-Encoding: gzip\r\n";
290	  }
291	  if (!supportsPersistentConnection()) {
292	    header += "Connection: close\r\n";
293	  }
294	  header += headers;
295	  header += "\r\n";
296	  A2_LOG_DEBUG(fmt("HTTP Server sends response:\n%s", header.c_str()));
297	  socketBuffer_.pushStr(std::move(header));
298	  socketBuffer_.pushStr(std::move(text));
299	}
