59	ssize_t sendCallback(wslay_event_context_ptr wsctx, const uint8_t* data,
60	                     size_t len, int flags, void* userData)
61	{
62	  WebSocketSession* session = reinterpret_cast<WebSocketSession*>(userData);
63	  const std::shared_ptr<SocketCore>& socket = session->getSocket();
64	  try {
65	    ssize_t r = socket->writeData(data, len);
66	    if (r == 0) {
67	      if (socket->wantRead() || socket->wantWrite()) {
68	        wslay_event_set_error(wsctx, WSLAY_ERR_WOULDBLOCK);
69	      }
70	      else {
71	        wslay_event_set_error(wsctx, WSLAY_ERR_CALLBACK_FAILURE);
72	      }
73	      r = -1;
74	    }
75	    return r;
76	  }
77	  catch (RecoverableException& e) {
78	    A2_LOG_DEBUG_EX(EX_EXCEPTION_CAUGHT, e);
79	    wslay_event_set_error(wsctx, WSLAY_ERR_CALLBACK_FAILURE);
80	    return -1;
81	  }
82	}
83	} // namespace
84	
85	namespace {
86	ssize_t recvCallback(wslay_event_context_ptr wsctx, uint8_t* buf, size_t len,
87	                     int flags, void* userData)
88	{
89	  WebSocketSession* session = reinterpret_cast<WebSocketSession*>(userData);
90	  const std::shared_ptr<SocketCore>& socket = session->getSocket();
91	  try {
92	    ssize_t r;
93	    socket->readData(buf, len);
94	    if (len == 0) {
95	      if (socket->wantRead() || socket->wantWrite()) {
96	        wslay_event_set_error(wsctx, WSLAY_ERR_WOULDBLOCK);
97	      }
98	      else {
99	        wslay_event_set_error(wsctx, WSLAY_ERR_CALLBACK_FAILURE);
100	      }
101	      r = -1;
102	    }
103	    else {
104	      r = len;
105	    }
106	    return r;
107	  }
108	  catch (RecoverableException& e) {
109	    A2_LOG_DEBUG_EX(EX_EXCEPTION_CAUGHT, e);
110	    wslay_event_set_error(wsctx, WSLAY_ERR_CALLBACK_FAILURE);
111	    return -1;
112	  }
113	}
114	} // namespace
115	
116	namespace {
117	void addResponse(WebSocketSession* wsSession, const RpcResponse& res)
118	{
119	  bool notauthorized = rpc::not_authorized(res);
120	  std::string response = toJson(res, "", false);
121	  wsSession->addTextMessage(response, notauthorized);
122	}
123	} // namespace
124	
125	namespace {
126	void addResponse(WebSocketSession* wsSession,
127	                 const std::vector<RpcResponse>& results)
128	{
129	  bool notauthorized = rpc::any_not_authorized(results.begin(), results.end());
130	  std::string response = toJsonBatch(results, "", false);
131	  wsSession->addTextMessage(response, notauthorized);
132	}
133	} // namespace
134	
135	namespace {
136	void onFrameRecvStartCallback(
137	    wslay_event_context_ptr wsctx,
138	    const struct wslay_event_on_frame_recv_start_arg* arg, void* userData)
139	{
140	  WebSocketSession* wsSession = reinterpret_cast<WebSocketSession*>(userData);
141	  wsSession->setIgnorePayload(wslay_is_ctrl_frame(arg->opcode));
142	}
143	} // namespace
144	
145	namespace {
146	void onFrameRecvChunkCallback(
147	    wslay_event_context_ptr wsctx,
148	    const struct wslay_event_on_frame_recv_chunk_arg* arg, void* userData)
149	{
150	  WebSocketSession* wsSession = reinterpret_cast<WebSocketSession*>(userData);
151	  if (!wsSession->getIgnorePayload()) {
152	    // The return value is ignored here. It will be evaluated in
153	    // onMsgRecvCallback.
154	    wsSession->parseUpdate(arg->data, arg->data_length);
155	  }
156	}
157	} // namespace
158	
159	namespace {
160	void onMsgRecvCallback(wslay_event_context_ptr wsctx,
161	                       const struct wslay_event_on_msg_recv_arg* arg,
162	                       void* userData)
163	{
164	  WebSocketSession* wsSession = reinterpret_cast<WebSocketSession*>(userData);
165	  if (!wslay_is_ctrl_frame(arg->opcode)) {
166	    // TODO Only process text frame
167	    ssize_t error = 0;
168	    auto json = wsSession->parseFinal(nullptr, 0, error);
169	    if (error < 0) {
170	      A2_LOG_INFO("Failed to parse JSON-RPC request");
171	      RpcResponse res(
172	          createJsonRpcErrorResponse(-32700, "Parse error.", Null::g()));
173	      addResponse(wsSession, res);
174	      return;
175	    }
176	    Dict* jsondict = downcast<Dict>(json);
177	    auto e = wsSession->getDownloadEngine();
178	    if (jsondict) {
179	      RpcResponse res = processJsonRpcRequest(jsondict, e);
180	      addResponse(wsSession, res);
181	    }
182	    else {
183	      List* jsonlist = downcast<List>(json);
184	      if (jsonlist) {
185	        // This is batch call
186	        std::vector<RpcResponse> results;
187	        for (List::ValueType::const_iterator i = jsonlist->begin(),
188	                                             eoi = jsonlist->end();
189	             i != eoi; ++i) {
190	          Dict* jsondict = downcast<Dict>(*i);
191	          if (jsondict) {
192	            auto resp = processJsonRpcRequest(jsondict, e);
193	            results.push_back(std::move(resp));
194	          }
195	        }
196	        addResponse(wsSession, results);
197	      }
198	      else {
199	        RpcResponse res(
200	            createJsonRpcErrorResponse(-32600, "Invalid Request.", Null::g()));
201	        addResponse(wsSession, res);
202	      }
203	    }
204	  }
205	  else {
206	    RpcResponse res(
207	        createJsonRpcErrorResponse(-32600, "Invalid Request.", Null::g()));
208	    addResponse(wsSession, res);
209	  }
210	}
211	} // namespace
