213	WebSocketSession::WebSocketSession(const std::shared_ptr<SocketCore>& socket,
214	                                   DownloadEngine* e)
215	    : socket_(socket),
216	      e_(e),
217	      ignorePayload_(false),
218	      receivedLength_(0),
219	      command_(nullptr)
220	{
221	  wslay_event_callbacks callbacks;
222	  memset(&callbacks, 0, sizeof(wslay_event_callbacks));
223	  callbacks.recv_callback = recvCallback;
224	  callbacks.send_callback = sendCallback;
225	  callbacks.on_msg_recv_callback = onMsgRecvCallback;
226	  callbacks.on_frame_recv_start_callback = onFrameRecvStartCallback;
227	  callbacks.on_frame_recv_chunk_callback = onFrameRecvChunkCallback;
228	
229	  int r = wslay_event_context_server_init(&wsctx_, &callbacks, this);
230	  assert(r == 0);
231	  wslay_event_config_set_no_buffering(wsctx_, 1);
232	}
233	
234	WebSocketSession::~WebSocketSession() { wslay_event_context_free(wsctx_); }
235	
236	bool WebSocketSession::wantRead() { return wslay_event_want_read(wsctx_); }
237	
238	bool WebSocketSession::wantWrite() { return wslay_event_want_write(wsctx_); }
239	
240	bool WebSocketSession::finish() { return !wantRead() && !wantWrite(); }
241	
242	int WebSocketSession::onReadEvent()
243	{
244	  if (wslay_event_recv(wsctx_) == 0) {
245	    return 0;
246	  }
247	  else {
248	    return -1;
249	  }
250	}
