263	class TextMessageCommand : public Command {
264	private:
265	  std::shared_ptr<WebSocketSession> session_;
266	  const std::string msg_;
267	
268	public:
269	  TextMessageCommand(cuid_t cuid, std::shared_ptr<WebSocketSession> session,
270	                     const std::string& msg)
271	      : Command(cuid), session_{std::move(session)}, msg_{msg}
272	  {
273	  }
274	  virtual bool execute() CXX11_OVERRIDE
275	  {
276	    session_->addTextMessage(msg_, false);
277	    return true;
278	  }
279	};
280	} // namespace
