282	void WebSocketSession::addTextMessage(const std::string& msg, bool delayed)
283	{
284	  if (delayed) {
285	    auto e = getDownloadEngine();
286	    auto cuid = command_->getCuid();
287	    auto c = make_unique<TextMessageCommand>(cuid, command_->getSession(), msg);
288	    e->addCommand(
289	        make_unique<DelayedCommand>(cuid, e, 1_s, std::move(c), false));
290	    return;
291	  }
292	
293	  // TODO Don't add text message if the size of outbound queue in
294	  // wsctx_ exceeds certain limit.
295	  wslay_event_msg arg = {WSLAY_TEXT_FRAME,
296	                         reinterpret_cast<const uint8_t*>(msg.c_str()),
297	                         msg.size()};
298	  wslay_event_queue_msg(wsctx_, &arg);
299	}
