312	{
313	  // Cap the number of bytes to feed the parser
314	  size_t maxlen = e_->getOption()->getAsInt(PREF_RPC_MAX_REQUEST_SIZE);
315	  if (receivedLength_ + len <= maxlen) {
316	    receivedLength_ += len;
317	  }
318	  else {
319	    len = 0;
320	  }
321	  return parser_.parseUpdate(reinterpret_cast<const char*>(data), len);
322	}
