325	WebSocketSession::parseFinal(const uint8_t* data, size_t len, ssize_t& error)
326	{
327	  auto res =
328	      parser_.parseFinal(reinterpret_cast<const char*>(data), len, error);
329	  receivedLength_ = 0;
330	  return res;
331	}
