68	void WebSocketSessionMan::addNotification(const std::string& method,
69	                                          const RequestGroup* group)
70	{
71	  auto dict = Dict::g();
72	  dict->put("jsonrpc", "2.0");
73	  dict->put("method", method);
74	  auto eventSpec = Dict::g();
75	  eventSpec->put("gid", GroupId::toHex((group->getGID())));
76	  auto params = List::g();
77	  params->append(std::move(eventSpec));
78	  dict->put("params", std::move(params));
79	  std::string msg = json::encode(dict.get());
80	  for (auto& session : sessions_) {
81	    session->addTextMessage(msg, false);
82	    session->getCommand()->updateWriteCheck();
83	  }
84	}
