97	const std::string& getMethodName(DownloadEvent event)
98	{
99	  switch (event) {
100	  case EVENT_ON_DOWNLOAD_START:
101	    return ON_DOWNLOAD_START;
102	  case EVENT_ON_DOWNLOAD_PAUSE:
103	    return ON_DOWNLOAD_PAUSE;
104	  case EVENT_ON_DOWNLOAD_STOP:
105	    return ON_DOWNLOAD_STOP;
106	  case EVENT_ON_DOWNLOAD_COMPLETE:
107	    return ON_DOWNLOAD_COMPLETE;
108	  case EVENT_ON_DOWNLOAD_ERROR:
109	    return ON_DOWNLOAD_ERROR;
110	  case EVENT_ON_BT_DOWNLOAD_COMPLETE:
111	    return ON_BT_DOWNLOAD_COMPLETE;
112	  default:
113	    // Not reachable
114	    assert(0);
115	    // For suppress compiler warning
116	    return A2STR::NIL;
117	  }
118	}
