50	AbstractHttpServerResponseCommand::AbstractHttpServerResponseCommand(
51	    cuid_t cuid, const std::shared_ptr<HttpServer>& httpServer,
52	    DownloadEngine* e, const std::shared_ptr<SocketCore>& socket)
53	    : Command(cuid),
54	      e_(e),
55	      socket_(socket),
56	      httpServer_(httpServer),
57	      readCheck_(false),
58	      writeCheck_(true)
59	{
60	  setStatus(Command::STATUS_ONESHOT_REALTIME);
61	  e_->addSocketForWriteCheck(socket_, this);
62	}
63	
64	AbstractHttpServerResponseCommand::~AbstractHttpServerResponseCommand()
65	{
66	  if (readCheck_) {
67	    e_->deleteSocketForReadCheck(socket_, this);
68	  }
69	  if (writeCheck_) {
70	    e_->deleteSocketForWriteCheck(socket_, this);
71	  }
72	}
73	
74	void AbstractHttpServerResponseCommand::updateReadWriteCheck()
75	{
76	  if (httpServer_->wantRead()) {
77	    if (!readCheck_) {
78	      readCheck_ = true;
79	      e_->addSocketForReadCheck(socket_, this);
80	    }
81	  }
82	  else if (readCheck_) {
83	    readCheck_ = false;
84	    e_->deleteSocketForReadCheck(socket_, this);
85	  }
86	  if (httpServer_->wantWrite()) {
87	    if (!writeCheck_) {
88	      writeCheck_ = true;
89	      e_->addSocketForWriteCheck(socket_, this);
90	    }
91	  }
92	  else if (writeCheck_) {
93	    writeCheck_ = false;
94	    e_->deleteSocketForWriteCheck(socket_, this);
95	  }
96	}
97	
98	bool AbstractHttpServerResponseCommand::execute()
99	{
100	  if (e_->getRequestGroupMan()->downloadFinished() || e_->isHaltRequested()) {
101	    return true;
102	  }
103	  try {
104	    ssize_t len = httpServer_->sendResponse();
105	    if (len > 0) {
106	      timeoutTimer_ = global::wallclock();
107	    }
108	  }
109	  catch (RecoverableException& e) {
110	    A2_LOG_INFO_EX(fmt("CUID#%" PRId64
111	                       " - Error occurred while transmitting response body.",
112	                       getCuid()),
113	                   e);
114	    return true;
115	  }
116	  if (httpServer_->sendBufferIsEmpty()) {
117	    A2_LOG_INFO(fmt("CUID#%" PRId64 " - HttpServer: all response transmitted.",
118	                    getCuid()));
119	    afterSend(httpServer_, e_);
120	    return true;
121	  }
122	  else {
123	    if (timeoutTimer_.difference(global::wallclock()) >= 30_s) {
124	      A2_LOG_INFO(fmt("CUID#%" PRId64
125	                      " - HttpServer: Timeout while transmitting response.",
126	                      getCuid()));
127	      return true;
128	    }
129	    else {
130	      updateReadWriteCheck();
131	      e_->addCommand(std::unique_ptr<Command>(this));
132	      return false;
133	    }
134	  }
135	}
