51	WebSocketInteractionCommand::WebSocketInteractionCommand(
52	    cuid_t cuid, const std::shared_ptr<WebSocketSession>& wsSession,
53	    DownloadEngine* e, const std::shared_ptr<SocketCore>& socket)
54	    : Command(cuid),
55	      e_(e),
56	      socket_(socket),
57	      writeCheck_(false),
58	      wsSession_(wsSession)
59	{
60	  e_->getWebSocketSessionMan()->addSession(wsSession_);
61	  e_->addSocketForReadCheck(socket_, this);
62	}
63	
64	WebSocketInteractionCommand::~WebSocketInteractionCommand()
65	{
66	  e_->deleteSocketForReadCheck(socket_, this);
67	  if (writeCheck_) {
68	    e_->deleteSocketForWriteCheck(socket_, this);
69	  }
70	  e_->getWebSocketSessionMan()->removeSession(wsSession_);
71	}
72	
73	void WebSocketInteractionCommand::updateWriteCheck()
74	{
75	  if (socket_->wantWrite() || wsSession_->wantWrite()) {
76	    if (!writeCheck_) {
77	      writeCheck_ = true;
78	      e_->addSocketForWriteCheck(socket_, this);
79	    }
80	  }
81	  else if (writeCheck_) {
82	    writeCheck_ = false;
83	    e_->deleteSocketForWriteCheck(socket_, this);
84	  }
85	}
86	
87	bool WebSocketInteractionCommand::execute()
88	{
89	  if (e_->isHaltRequested()) {
90	    return true;
91	  }
92	  if (wsSession_->onReadEvent() == -1 || wsSession_->onWriteEvent() == -1) {
93	    if (wsSession_->closeSent() || wsSession_->closeReceived()) {
94	      A2_LOG_INFO(
95	          fmt("CUID#%" PRId64 " - WebSocket session terminated.", getCuid()));
96	    }
97	    else {
98	      A2_LOG_INFO(fmt("CUID#%" PRId64 " - WebSocket session terminated"
99	                      " (Possibly due to EOF).",
100	                      getCuid()));
101	    }
102	    return true;
103	  }
104	  if (wsSession_->finish()) {
105	    return true;
106	  }
107	  updateWriteCheck();
108	  e_->addCommand(std::unique_ptr<Command>(this));
109	  return false;
110	}
