41	namespace aria2 {
42	
43	// DiskWriter backed with ValueBaseParser. The written bytes are
44	// consumed by ValueBaseParser. It is only capable of sequential write
45	// so offset argument in write() will be ignored. It also does not
46	// offer read().
47	template <class ValueBaseParser> class ValueBaseDiskWriter : public DiskWriter {
48	public:
49	  ValueBaseDiskWriter() : parser_(&psm_) {}
50	
51	  virtual ~ValueBaseDiskWriter() = default;
52	
53	  virtual void initAndOpenFile(int64_t totalLength = 0) CXX11_OVERRIDE
54	  {
55	    parser_.reset();
56	  }
57	
58	  virtual void openFile(int64_t totalLength = 0) CXX11_OVERRIDE
59	  {
60	    initAndOpenFile(totalLength);
61	  }
62	
63	  virtual void closeFile() CXX11_OVERRIDE {}
64	
65	  virtual void openExistingFile(int64_t totalLength = 0) CXX11_OVERRIDE
66	  {
67	    initAndOpenFile(totalLength);
68	  }
69	
70	  virtual int64_t size() CXX11_OVERRIDE { return 0; }
71	
72	  virtual void writeData(const unsigned char* data, size_t len,
73	                         int64_t offset) CXX11_OVERRIDE
74	  {
75	    // Return value is ignored here but handled in finalize()
76	    parser_.parseUpdate(reinterpret_cast<const char*>(data), len);
77	  }
78	
79	  virtual ssize_t readData(unsigned char* data, size_t len,
80	                           int64_t offset) CXX11_OVERRIDE
81	  {
82	    return 0;
83	  }
84	
85	  int finalize() { return parser_.parseFinal(0, 0); }
86	
87	  std::unique_ptr<ValueBase> getResult() { return psm_.getResult(); }
88	
89	  void reset() { parser_.reset(); }
90	
91	private:
92	  ValueBaseStructParserStateMachine psm_;
93	  ValueBaseParser parser_;
94	};
